//! Identical HTTP harness for baseline and candidate checkouts (ORB-11205).
//! Fixtures are generated by orbit-store's ignored task_list_io_benchmark.

use std::path::PathBuf;
use std::time::Instant;

use axum::body::{Body, to_bytes};
use axum::http::{Request, StatusCode};
use orbit_core::{ShipMode, runtime::WorkspaceRuntimeBinding};
use serde_json::Value;
use tower::ServiceExt;

use super::super::router;
use crate::state::{DashboardState, WsEntry};

async fn request(state: DashboardState, uri: &str) -> usize {
    let response = router()
        .with_state(state)
        .oneshot(Request::builder().uri(uri).body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(response.status(), StatusCode::OK, "{uri}");
    to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap()
        .len()
}

#[tokio::test(flavor = "current_thread")]
#[ignore = "generated corpus HTTP response benchmark"]
#[allow(clippy::print_stdout)]
async fn task_response_benchmark() {
    let root =
        PathBuf::from(std::env::var_os("ORBIT_TASK_BENCH_ROOT").expect("generated fixture root"));
    assert!(
        root.starts_with(std::env::temp_dir()),
        "temporary fixtures only"
    );
    let mode = std::env::var("ORBIT_TASK_BENCH_MODE").unwrap();
    let size: usize = std::env::var("ORBIT_TASK_BENCH_SIZE")
        .unwrap()
        .parse()
        .unwrap();
    let entries = (0..3)
        .map(|n| {
            let id = format!("ws_bench_{n}");
            let repo_root = root.join(&id);
            WsEntry {
                id: id.clone(),
                name: id.clone(),
                orbit_dir: repo_root.join(".orbit"),
                repo_root: repo_root.clone(),
                active: true,
                binding: Some(WorkspaceRuntimeBinding {
                    workspace_id: id.clone(),
                    logical_workspace_id: id,
                    repo_root,
                    ship_mode: ShipMode::Local,
                }),
            }
        })
        .collect();
    let state = DashboardState::global(root.clone(), entries, Some("ws_bench_0".to_string()));
    let mut ids = std::fs::read_dir(root.join("tasks/workspaces/ws_bench_0"))
        .unwrap()
        .map(|entry| entry.unwrap().file_name().to_string_lossy().into_owned())
        .filter(|name| name.starts_with("ORB-"))
        .collect::<Vec<_>>();
    ids.sort();
    let detail = format!("/tasks/{}?workspace=ws_bench_0", ids[0]);
    for (name, uri) in [
        ("list", "/tasks?workspace=ws_bench_0"),
        ("selective", "/tasks?workspace=ws_bench_0&tag=selective"),
        ("detail", detail.as_str()),
        ("aggregate", "/tasks/all"),
    ] {
        request(state.clone(), uri).await;
        let mut samples = Vec::new();
        let mut bytes = 0;
        for _ in 0..11 {
            let start = Instant::now();
            bytes = request(state.clone(), uri).await;
            samples.push(start.elapsed().as_secs_f64() * 1000.0);
        }
        report(&mode, size, name, &mut samples, bytes);
    }
    let mut responsiveness = Vec::new();
    for _ in 0..11 {
        let (entered_tx, entered_rx) = tokio::sync::oneshot::channel();
        let first_state = state.clone();
        let mut pending = vec![tokio::spawn(async move {
            entered_tx.send(Instant::now()).unwrap();
            request(first_state, "/tasks?workspace=ws_bench_0").await
        })];
        for _ in 0..3 {
            let state = state.clone();
            pending.push(tokio::spawn(async move {
                request(state, "/tasks?workspace=ws_bench_0").await
            }));
        }
        let start = entered_rx.await.unwrap();
        request(state.clone(), "/workspaces").await;
        responsiveness.push(start.elapsed().as_secs_f64() * 1000.0);
        for request in pending {
            request.await.unwrap();
        }
    }
    report(
        &mode,
        size,
        "unrelated_under_four_lists",
        &mut responsiveness,
        0,
    );
}

#[allow(clippy::print_stdout)]
fn report(mode: &str, size: usize, operation: &str, samples: &mut [f64], bytes: usize) {
    samples.sort_by(f64::total_cmp);
    let status = std::fs::read_to_string("/proc/self/status").unwrap();
    let hwm = status
        .lines()
        .find(|line| line.starts_with("VmHWM:"))
        .unwrap();
    let value: Value = serde_json::json!({"mode": mode, "per_workspace": size, "workspaces": 3,
        "operation": operation, "median_ms": samples[5], "p95_ms": samples[10],
        "response_bytes": bytes, "peak_rss_setup_inclusive": hwm, "samples": samples.len(),
        "cache": "warm tmpfs; no cold-cache control"});
    println!("{value}");
}
